const rawRecordId = pm.variables.get("saturation_record_id");

if (!rawRecordId) {
    throw new Error("saturation_record_id is not defined");
}

const storageRecordId = rawRecordId.replace(/:+$/, "");
const referenceRecordId = `${storageRecordId}:`;

const host = pm.variables.get("HOSTNAME");
const accessToken = pm.environment.get("access_token");
const partition = pm.environment.get("data-partition-id");

const rowsFilter = encodeURIComponent(
    `SaturationFunctionSetID,eq,${referenceRecordId}`
);

const url =
    `https://${host}/api/rafs-ddms/v2/saturationfunctionset/search` +
    `?rows_filter=${rowsFilter}`;

const maxAttempts = 60;
const intervalMs = 2000;
let attempt = 0;

function pollForRecord() {
    pm.sendRequest(
        {
            url,
            method: "GET",
            header: {
                Authorization: `Bearer ${accessToken}`,
                "data-partition-id": partition,
                Accept: "*/*;version=1.0.0"
            }
        },
        function (error, response) {
            attempt += 1;

            if (!error && response.code === 200) {
                const body = response.json();
                const result = Array.isArray(body.result)
                    ? body.result.map(id => id.replace(/:+$/, ""))
                    : [];

                if (result.includes(storageRecordId)) {
                    console.log(
                        `Saturation Function Set indexed after ${attempt} attempts`
                    );
                    return;
                }
            }

            if (attempt >= maxAttempts) {
                throw new Error(
                    `Saturation Function Set ${storageRecordId} was not indexed ` +
                    `after ${maxAttempts} attempts`
                );
            }

            setTimeout(pollForRecord, intervalMs);
        }
    );
}

pollForRecord();

