pm.test("Record_id visible under search results'", function () {
    var jsonData = pm.response.json();
    let depth_shift_record_id = pm.variables.get("depth_shift_record_id")
    pm.expect(jsonData.result).to.include(depth_shift_record_id);
    pm.expect(jsonData.result).to.be.an("array").with.lengthOf(1);
});

const rawRecordId = pm.variables.get("depth_shift_record_id");

if (!rawRecordId) {
    throw new Error("depth_shift_record_id is not defined");
}

const storageRecordId = rawRecordId.replace(/:+$/, "");
const referenceRecordId = `${storageRecordId}:`;

const host = pm.variables.get("HOSTNAME");
const accessToken = pm.environment.get("access_token");
const partition = pm.environment.get("data-partition-id");

const rowsFilter = encodeURIComponent(
    `DepthShiftWPCID,eq,${referenceRecordId}`
);

const url =
    `https://${host}/api/rafs-ddms/v2/depthshift/search` +
    `?rows_filter=${rowsFilter}`;

const maxAttempts = 60;
const intervalMs = 2000;
let attempt = 0;

function pollForRecord() {
    pm.sendRequest(
        {
            url,
            method: "GET",
            header: {
                Authorization: `Bearer ${accessToken}`,
                "data-partition-id": partition,
                Accept: "*/*;version=1.0.0"
            }
        },
        function (error, response) {
            attempt += 1;

            if (!error && response.code === 200) {
                let body;

                try {
                    body = response.json();
                } catch (parseError) {
                    console.log(
                        `Attempt ${attempt}: Search returned a non-JSON response`
                    );
                }

                const result =
                    body && Array.isArray(body.result)
                        ? body.result.map(id => id.replace(/:+$/, ""))
                        : [];

                if (result.includes(storageRecordId)) {
                    console.log(
                        `Depth Shift indexed after ${attempt} attempts`
                    );
                    return;
                }
            } else {
                console.log(
                    `Attempt ${attempt}: ${
                        error || `HTTP ${response.code}`
                    }`
                );
            }

            if (attempt >= maxAttempts) {
                throw new Error(
                    `Depth Shift ${storageRecordId} was not indexed after ` +
                    `${maxAttempts} attempts`
                );
            }

            setTimeout(pollForRecord, intervalMs);
        }
    );
}

pollForRecord();
